EvalSuiteDetail {"type": "object", "required": ["id", "environment", "hosts", "settings", "schedule"], "description": "One eval suite's full configuration. Distinct from the `EvalSuite` summary returned by the list route, which carries run rollups instead of settings.", "properties": {"id": {"type": "string"}, "declaredId": {"type": "string", "description": "The suite's declared file identity (`suite.id` in a suite file). Present on file-owned suites; absent on UI-authored suites, which have no declared id and cannot be claimed by `eval run --file`."}, "managedBy": {"type": "string", "description": "Where this suite's configuration lives. `ci` means it is owned by a committed suite file or by MCPJam SDK ingest, and the platform REFUSES configuration writes to it \u2014 name, settings, environments, schedule, models, skills, execution config and cases \u2014 from this API and from the app alike, with `409 CONFLICT` and `details.reason: \"CI_OWNED_SUITE_READ_ONLY\"`.\n\nRunning, replaying, comparing and DELETING are unaffected \u2014 deleting a suite is not editing one, and it is the only cleanup an SDK-created suite has. To change a CI-owned suite, either edit its file and send that file's `suite.id` as `declaredSuiteId` on the write, or duplicate the suite for an editable copy.\n\n`declaredId` alone is not this answer: a suite created by SDK ingest is CI-owned and has no declared id.", "enum": ["ci", "app"]}, "name": {"type": ["string", "null"]}, "description": {"type": ["string", "null"]}, "projectId": {"type": ["string", "null"]}, "environment": {"type": "object", "description": "LEGACY server bag, kept as rollback data, plus the suite's sandbox-image pin. Unrelated to `environmentIds`.", "properties": {"servers": {"type": "array", "items": {"type": "string"}}, "computerEnvironment": {"anyOf": [{"$ref": "#/components/schemas/EvalSuiteComputerEnvironment"}, {"type": "null"}], "description": "The custom sandbox image this suite's eval runs boot a fresh computer from. `null` means the provider's default base image. PATCH it by name or id (see `GET /projects/{projectId}/images`); PATCH `null` to clear the pin."}}}, "executionConfig": {"type": ["object", "null"], "properties": {"model": {"type": "string", "readOnly": true, "description": "COMPUTED in responses: the selection's `modelId` when there is one, else the stored bare id. Accepted on writes as a shorthand: send a bare id and the platform converts it (a hosted id becomes a `hosted` selection, any other a `LegacyModelSelection`)."}, "systemPrompt": {"type": "string"}, "temperature": {"type": "number"}, "modelSelection": {"allOf": [{"$ref": "#/components/schemas/RequestedModelSelection"}], "description": "The saved model choice behind `model` (source, connection, `settings.reasoningEffort`). Absent when the suite pins only a bare model id. May be a STORED legacy selection (`LegacyModelSelection`, `source: \"legacy\"`): own key only, never MCPJam credits. The model id beside it is computed from it."}, "modelSelectionOrigin": {"type": "string", "enum": ["backfill"], "description": "`backfill` when a conversion (a save of a bare id, or the old-data backfill) chose `modelSelection` rather than a person. Absent when a person chose it, and on rows with no selection."}}}, "hosts": {"type": "array", "items": {"type": "object", "required": ["id", "name"], "properties": {"id": {"type": "string"}, "name": {"type": "string"}, "servers": {"type": "array", "items": {"type": "string"}}}}}, "environmentIds": {"type": "array", "description": "Attached project environments, in attach order.", "items": {"type": "string"}}, "settings": {"$ref": "#/components/schemas/EvalSuiteSettings"}, "schedule": {"$ref": "#/components/schemas/EvalSuiteSchedule"}, "revisionNumber": {"type": ["integer", "null"], "description": "How many committed edits this suite has had, or `null` on a deployment that does not record revisions. Send it back as `expectedRevisionNumber` on a PATCH to make that edit a compare-and-set."}, "createdAt": {"type": ["number", "null"], "description": "Epoch milliseconds."}, "updatedAt": {"type": ["number", "null"]}}}
